  (out/f'{mode}-{name}-excerpt.json').write_text(json.dumps(snippet,indent=2,ensure_ascii=False)+'\\n')
  if mode=='tui':
   for screen in ['before-guidance','guidance-submitted','completed']:shutil.copyfile(d/(screen+'.txt'),out/f'tui-{name}-{screen}.txt')
  real.append({'mode':mode,'enabled':name=='enabled','rawDirectory':str(d.relative_to(root)),'requests':len(requests),'obsoleteExists':(d/'obsolete.md').exists(),'summary':(d/'SUMMARY.md').read_text()})
